
/* ==========================================================================
   Hagah v6 shell — calm home (greeting + Verse of the Day + one guided card)
   and a five-door bottom tab bar: Home · Bible · Study · Sermon · Plans.
   Like the rebuild layer, this drives the app ONLY through its own UI:
   the mode switch [data-hg-mode], the module tabs [data-hg-tab], the
   sub-view buttons [data-hg-subview], the Study Helps .sh-tab buttons and
   the reader's own book/chapter selects + Read button. No engine internals
   are modified, nothing is written for the user, and there are no network
   calls. The old #hg-home layer is superseded on Home only (hidden by the
   v6 theme); every feature behind it is reachable through the doors.
   ========================================================================== */
(function () {
  'use strict';
  function $(s, r) { return (r || document).querySelector(s); }
  function $$(s, r) { return Array.prototype.slice.call((r || document).querySelectorAll(s)); }
  function sleep(ms) { return new Promise(function (r) { setTimeout(r, ms); }); }
  function esc(s) { return String(s == null ? '' : s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }

  /* ---- v2 hero photo (#213-A): a bright mist/light scenic generated locally
     with Python PIL (snowy ridge, morning fog, dark tree line). Embedding
     route, chosen by evidence: the app's own CSP meta (default-src 'none',
     no img-src) blocks EVERY image load — data:, file: and blob: img elements and
     CSS backgrounds alike (probe-verified) — so the generated image is
     embedded as palette+RLE pixel data and painted onto <canvas> by the
     shell. Still zero network references; the asset lives in this layer. */
  var HG6_HERO_PX = { w: 512, h: 640, pal: '', runs: '' };
  function hg6HeroCanvas() {
    var b64 = function (s) { var bin = atob(s), u = new Uint8Array(bin.length); for (var i = 0; i < bin.length; i++) { u[i] = bin.charCodeAt(i); } return u; };
    var pal = b64(HG6_HERO_PX.pal), runs = b64(HG6_HERO_PX.runs);
    var cv = document.createElement('canvas'); cv.width = HG6_HERO_PX.w; cv.height = HG6_HERO_PX.h;
    var ctx = cv.getContext('2d'); var imgData = ctx.createImageData(HG6_HERO_PX.w, HG6_HERO_PX.h); var d = imgData.data;
    var o = 0;
    for (var i = 0; i + 2 < runs.length; i += 3) {
      var cnt = runs[i] | (runs[i + 1] << 8), pi = runs[i + 2] * 3, r = pal[pi], g = pal[pi + 1], bl = pal[pi + 2];
      for (var k = 0; k < cnt; k++) { d[o] = r; d[o + 1] = g; d[o + 2] = bl; d[o + 3] = 255; o += 4; }
    }
    ctx.putImageData(imgData, 0, 0);
    return cv;
  }
  function paintHeroInto(target) {
    if (!target) { return; }
    target.width = HG6_HERO_PX.w; target.height = HG6_HERO_PX.h;
    var ctx = target.getContext('2d');
    if (ctx) { ctx.drawImage(hg6HeroCanvas(), 0, 0); }
  }

  /* ---- Verse of the Day (upgraded 2026-10-22, staged; Gate 0 NOT pulled).
     Ruling (Donnie, 2026-10-21 20:03 MDT): our own rotating verse from the
     app's public-domain texts ONLY — no Our Daily Bread link-out, no
     external fetch, ever.
     What changed from the original v6 surface (31 refs, day-of-month cycle,
     Geneva wording bundled as hand-typed text in this file):
       - 90 curated references (45 Old + 45 New Testament), references ONLY
         as data — no Scripture text is typed into this file any more (the
         old bundled texts were excerpts with transcription risk: e.g.
         Galatians 5:22 ended mid-list at "faith,").
       - Rotation is deterministic by calendar date: days since epoch
         (local) mod 90 — same verse all day, changes at local midnight,
         no repeats until the 90-verse list cycles, nothing stored.
       - The verse TEXT is resolved at runtime from the app's own shipped
         KJV, data/translations/kjv.json — the exact file the reader and
         Compare load (KJV is the house default for this surface). One
         fetch of the app's own file: XMLHttpRequest on purpose, because
         the split loader holds window.fetch for the five Compare files
         until the Geneva flood settles; the service worker serves the
         file cache-first, so after the first online open the verse works
         fully offline. If the KJV cannot be loaded (offline before any
         cache exists), the fallback is the reader's own resident Geneva
         text, labeled as Geneva — never a hand-typed copy, and never a
         Geneva text wearing a KJV label. ---- */
  var VOTD_REFS = [
    [1,1,1],
    [1,1,27],
    [1,15,6],
    [1,28,15],
    [1,50,20],
    [2,14,14],
    [2,15,2],
    [2,20,2],
    [3,19,18],
    [5,31,6],
    [5,31,8],
    [6,1,8],
    [6,1,9],
    [9,16,7],
    [18,19,25],
    [18,42,2],
    [19,1,1],
    [19,1,3],
    [19,19,14],
    [19,23,1],
    [19,27,14],
    [19,34,8],
    [19,37,4],
    [19,46,1],
    [19,55,22],
    [19,90,12],
    [19,103,2],
    [19,118,24],
    [19,119,105],
    [19,121,2],
    [19,139,14],
    [20,3,5],
    [20,3,6],
    [20,16,3],
    [20,18,10],
    [21,3,1],
    [21,12,7],
    [23,40,31],
    [23,41,10],
    [23,43,1],
    [23,53,5],
    [24,17,7],
    [24,29,11],
    [24,31,3],
    [25,3,22],
    [40,5,9],
    [40,5,16],
    [40,6,34],
    [40,7,7],
    [40,11,28],
    [40,11,29],
    [41,10,27],
    [42,2,11],
    [42,10,27],
    [42,19,10],
    [43,1,1],
    [43,3,16],
    [43,3,17],
    [43,8,12],
    [43,10,10],
    [43,11,25],
    [43,13,34],
    [43,14,6],
    [43,14,27],
    [43,15,5],
    [43,15,13],
    [44,1,8],
    [44,4,12],
    [45,1,16],
    [45,15,13],
    [45,8,28],
    [45,8,38],
    [45,12,2],
    [46,13,13],
    [47,5,17],
    [48,2,20],
    [48,5,22],
    [49,2,8],
    [49,3,20],
    [50,4,6],
    [50,4,13],
    [51,3,23],
    [52,5,17],
    [55,3,16],
    [58,11,1],
    [58,13,8],
    [59,1,5],
    [60,5,7],
    [62,4,19],
    [66,3,20]
  ];
  var VOTD_TRANSLATION = 'KJV';
  function votdDayNumber(d) {
    return Math.floor(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()) / 86400000);
  }
  function votdRefFor(d) {
    var n = votdDayNumber(d) % VOTD_REFS.length;
    if (n < 0) { n += VOTD_REFS.length; }
    return VOTD_REFS[n];
  }
  function votdBookNames() {
    try { if (window.SSB && SSB.db() && SSB.db().books) { return SSB.db().books; } } catch (e) {}
    return (window.HAGAH_PD_TEXTS && HAGAH_PD_TEXTS.books) || [];
  }
  function votdRefLabel(ref) {
    var names = votdBookNames();
    return (names[ref[0] - 1] || ('Book ' + ref[0])) + ' ' + ref[1] + ':' + ref[2];
  }
  var votdKjv = null, votdKjvState = 'idle'; // idle | loading | ready | failed
  function votdResidentKjv() {
    try {
      var hd = window.HAGAH_DATA || {};
      return hd['translations/kjv.json'] || hd['translations/kjv'] || null;
    } catch (e) { return null; }
  }
  function votdLoadKjv(done) {
    var r = votdResidentKjv();
    if (r) { votdKjv = r; votdKjvState = 'ready'; done(r); return; }
    if (votdKjvState === 'ready') { done(votdKjv); return; }
    if (votdKjvState === 'loading') {
      var wait = setInterval(function () {
        if (votdKjvState !== 'loading') { clearInterval(wait); done(votdKjvState === 'ready' ? votdKjv : null); }
      }, 150);
      setTimeout(function () { clearInterval(wait); }, 20000);
      return;
    }
    votdKjvState = 'loading';
    try {
      var xhr = new XMLHttpRequest();
      xhr.open('GET', 'data/translations/kjv.json', true);
      xhr.onreadystatechange = function () {
        if (xhr.readyState !== 4) { return; }
        if (xhr.status >= 200 && xhr.status < 300) {
          try { votdKjv = JSON.parse(xhr.responseText); votdKjvState = 'ready'; done(votdKjv); return; }
          catch (e) { /* fall through */ }
        }
        votdKjvState = 'failed'; done(null);
      };
      xhr.onerror = function () { votdKjvState = 'failed'; done(null); };
      xhr.send();
    } catch (e) { votdKjvState = 'failed'; done(null); }
  }
  function votdGenevaText(ref) {
    try {
      var live = window.SSB_DATA && window.SSB_DATA.bible &&
        window.SSB_DATA.bible[String(ref[0])] &&
        window.SSB_DATA.bible[String(ref[0])][String(ref[1])] &&
        window.SSB_DATA.bible[String(ref[0])][String(ref[1])][String(ref[2])];
      return (typeof live === 'string' && live.length) ? live : null;
    } catch (e) { return null; }
  }
  function vodForToday() {
    var ref = votdRefFor(new Date());
    var out = { book: ref[0], chapter: ref[1], verse: ref[2], ref: votdRefLabel(ref), text: '', source: 'kjv-loading' };
    var kjv = votdResidentKjv() || (votdKjvState === 'ready' ? votdKjv : null);
    if (kjv) {
      try {
        var t = kjv.bible[String(ref[0])][String(ref[1])][String(ref[2])];
        if (typeof t === 'string' && t) { out.text = t; out.source = 'kjv-file'; return out; }
      } catch (e) { /* fall through to load */ }
    }
    votdLoadKjv(function () { refreshVodText(); });
    return out;
  }
  /* When the KJV lands after the home already rendered, fill the hero in —
     but only if the home is still showing the same day's verse. */
  function refreshVodText() {
    if (!currentVod || currentVod.source === 'kjv-file') { return; }
    var ref = [currentVod.book, currentVod.chapter, currentVod.verse];
    var text = null, source = 'unavailable';
    if (votdKjv) {
      try {
        var t = votdKjv.bible[String(ref[0])][String(ref[1])][String(ref[2])];
        if (typeof t === 'string' && t) { text = t; source = 'kjv-file'; }
      } catch (e) { /* fall through */ }
    }
    if (!text) {
      var g = votdGenevaText(ref);
      if (g) { text = g; source = 'geneva-fallback'; }
    }
    currentVod.text = text || 'Could not load today\u2019s verse here \u2014 tap Read the chapter to open it in the reader.';
    currentVod.source = source;
    var vt = $('#hg6-verse');
    if (vt) {
      vt.textContent = '\u201C' + currentVod.text + '\u201D';
      vt.style.fontSize = currentVod.text.length > 170 ? '1.3rem' : currentVod.text.length > 125 ? '1.45rem' : '1.58rem';
    }
    var rf = $('#hg6-ref');
    if (rf) { rf.textContent = currentVod.ref + (source === 'geneva-fallback' ? ' \u00B7 Geneva Bible 1599' : ' \u00B7 ' + VOTD_TRANSLATION); }
    var hero = $('#hg6-hero');
    if (hero) { hero.setAttribute('data-hg6-vod-source', source); }
  }

  function greeting() {
    var h = new Date().getHours();
    if (h < 12) { return 'Good morning'; }
    if (h < 18) { return 'Good afternoon'; }
    return 'Good evening';
  }

  /* ---- drive the app through its own UI (same pattern as the rebuild) ---- */
  function currentMode() {
    var b = $('[data-hg-mode][aria-pressed="true"]');
    return b ? b.getAttribute('data-hg-mode') : 'study';
  }
  async function ensureMode(m) {
    if (currentMode() === m) { return; }
    var b = $('[data-hg-mode="' + m + '"]');
    if (b) { b.click(); await sleep(110); }
  }
  async function gotoTab(id) {
    var b = $('[data-hg-tab="' + id + '"]');
    if (!b) { return false; }
    if (b.getAttribute('aria-current') !== 'page') { b.click(); await sleep(110); }
    return true;
  }
  async function gotoSub(v) {
    var b = $('[data-hg-subview="' + v + '"]');
    if (!b) { return false; }
    b.click(); await sleep(110); return true;
  }
  async function exitFlowIfActive() {
    var fb = $('#hg-flowbar');
    if (fb && !fb.hidden) {
      var ex = $('#hg-flow-exit');
      if (ex) { ex.click(); await sleep(90); }
    }
    var old = $('#hg-home');
    if (old) { old.hidden = true; }
  }

  /* ---- reading-plan state: the Study Helps store keys, read-only here.
     Shell store prefixes keys with 'hagah.', so plan progress lives at
     localStorage 'hagah.plans.<id>' = { startedAt, doneDays }. ---- */
  function planDayInfo(plan, day) {
    if (!plan || day < 1 || day > plan.days) { return null; }
    if (plan.kind === 'explicit') {
      var e = (plan.days_list || [])[day - 1];
      return e ? { kind: e.kind, ref: e.ref || null, scope: e.scope || null, note: e.note || '' } : null;
    }
    if (plan.kind === 'weekly') {
      var weekday = ((day - 1) % 7) + 1;
      if ((plan.grace_weekdays || []).indexOf(weekday) >= 0) {
        return { kind: 'grace', ref: null, scope: null, note: 'Grace day — catch up on missed readings, or rest.' };
      }
      var week = Math.floor((day - 1) / 7);
      var idx = week * (plan.read_weekdays || []).length + (plan.read_weekdays || []).indexOf(weekday);
      var chapters = plan.chapters || [];
      if (idx < 0 || idx >= chapters.length) {
        return { kind: 'grace', ref: null, scope: null, note: 'Grace day — catch up on missed readings, or rest.' };
      }
      return { kind: 'read', ref: chapters[idx], scope: null, note: 'Read ' + chapters[idx] + '.' };
    }
    return null;
  }
  function readPlanState() {
    var plans = [];
    try {
      var rp = window.HAGAH_DATA && window.HAGAH_DATA['reading-plans'];
      plans = (rp && rp.plans) || [];
    } catch (e) { plans = []; }
    if (!plans.length) { return null; }
    for (var i = 0; i < plans.length; i++) {
      var plan = plans[i], prog = null;
      try {
        var raw = window.localStorage.getItem('hagah.plans.' + plan.id);
        prog = raw ? JSON.parse(raw) : null;
      } catch (e) { prog = null; }
      if (prog && prog.startedAt && Array.isArray(prog.doneDays) && prog.doneDays.length < plan.days) {
        var next = null;
        for (var d = 1; d <= plan.days; d++) {
          if (prog.doneDays.indexOf(d) === -1) { next = d; break; }
        }
        if (next !== null) {
          return { mode: 'continue', plan: plan, day: next, info: planDayInfo(plan, next) };
        }
      }
    }
    var first = plans[0];
    return { mode: 'start', plan: first, day: 1, info: planDayInfo(first, 1) };
  }

  /* ---- doors ---- */
  var activeDoor = 'home';
  var FLOW_BY_DOOR = { bible: 'study', study: 'compare', sermon: 'sermon' };
  function updateFlowEntries() {
    var want = FLOW_BY_DOOR[activeDoor] || null;
    var wrap = $('#hg6-flows');
    $$('.hg6-flow-entry').forEach(function (b) {
      b.hidden = b.getAttribute('data-hg6-start-flow') !== want;
    });
    if (wrap) { wrap.hidden = !want; }
  }
  function setActive(door) {
    activeDoor = door;
    updateFlowEntries();
    $$('#hg6-tabbar .hg6-door').forEach(function (b) {
      var on = b.getAttribute('data-hg6-door') === door;
      b.classList.toggle('hg6-on', on);
      if (on) { b.setAttribute('aria-current', 'page'); } else { b.removeAttribute('aria-current'); }
    });
  }
  function showHome6() {
    var old = $('#hg-home');
    if (old) { old.hidden = true; }
    renderHome();
    var h = $('#hg6-home');
    if (h) { h.hidden = false; }
    document.body.classList.add('hg6-home-on');
    setActive('home');
    window.scrollTo(0, 0);
  }
  function hideHome6() {
    var h = $('#hg6-home');
    if (h) { h.hidden = true; }
    document.body.classList.remove('hg6-home-on');
  }
  async function goHome() { await exitFlowIfActive(); showHome6(); }
  async function goBible() {
    hideHome6(); await exitFlowIfActive();
    await gotoTab('scripture'); await gotoSub('study');
    setActive('bible'); window.scrollTo(0, 0);
  }
  async function goStudy() {
    hideHome6(); await exitFlowIfActive();
    await ensureMode('study');
    await gotoTab('study-helps');
    setActive('study'); window.scrollTo(0, 0);
  }
  async function goSermon() {
    hideHome6(); await exitFlowIfActive();
    await ensureMode('sermon');
    await gotoTab('sermon');
    var ok = await gotoSub('setup');
    if (!ok) { await gotoSub('start'); }
    setActive('sermon'); window.scrollTo(0, 0);
  }
  async function goPlans() {
    hideHome6(); await exitFlowIfActive();
    await ensureMode('study');
    await gotoTab('study-helps');
    var tabs = $$('.sh-tab');
    for (var i = 0; i < tabs.length; i++) {
      if (tabs[i].textContent.indexOf('Reading Plans') !== -1) { tabs[i].click(); break; }
    }
    await sleep(90);
    setActive('plans'); window.scrollTo(0, 0);
  }
  async function readChapter(vod) {
    hideHome6(); await exitFlowIfActive();
    await gotoTab('scripture'); await gotoSub('study');
    var b = $('#st-book'), c = $('#st-chapter');
    if (b) {
      b.value = String(vod.book);
      b.dispatchEvent(new Event('change', { bubbles: true }));
      await sleep(90);
    }
    if (c) { c.value = String(vod.chapter); }
    var go = $('#st-go');
    if (go) { go.click(); }
    await sleep(90);
    setActive('bible'); window.scrollTo(0, 0);
  }

  /* ---- render home ---- */
  var currentVod = null;
  function renderHome() {
    currentVod = vodForToday();
    var g = $('#hg6-greet'); if (g) { g.textContent = greeting(); }
    var dt = $('#hg6-date');
    if (dt) {
      dt.textContent = new Date().toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });
    }
    var vt = $('#hg6-verse');
    if (vt) {
      vt.textContent = currentVod.text ? '\u201C' + currentVod.text + '\u201D' : 'Loading today\u2019s verse\u2026';
      vt.style.fontSize = currentVod.text.length > 170 ? '1.3rem' : currentVod.text.length > 125 ? '1.45rem' : '1.58rem';
    }
    var rf = $('#hg6-ref');
    if (rf) { rf.textContent = currentVod.ref + ' \u00B7 ' + VOTD_TRANSLATION; }
    var hero = $('#hg6-hero');
    if (hero) { hero.setAttribute('data-hg6-vod-source', currentVod.source); hero.setAttribute('data-hg6-vod-ref', currentVod.ref); }
    var st = readPlanState();
    var name = $('#hg6-guided-name'), sub = $('#hg6-guided-sub'), cta = $('#hg6-guided-cta');
    if (st && st.mode === 'continue') {
      if (name) { name.textContent = st.plan.title; }
      if (sub) {
        sub.textContent = 'Day ' + st.day + ' of ' + st.plan.days +
          (st.info && st.info.ref ? ' — ' + st.info.ref :
           st.info && st.info.scope ? ' — look back over ' + st.info.scope :
           st.info && st.info.kind === 'grace' ? ' — a grace day: catch up, or rest' : '');
      }
      if (cta) { cta.textContent = 'Continue your plan →'; }
    } else if (st) {
      if (name) { name.textContent = st.plan.title; }
      if (sub) {
        sub.textContent = st.info && st.info.ref ? 'Day 1 \u2014 ' + st.info.ref :
          st.info && st.info.scope ? 'Day 1 \u2014 look back over ' + st.info.scope : 'Day 1';
      }
      if (cta) { cta.textContent = 'Start this plan →'; }
    } else {
      if (name) { name.textContent = 'Reading Plans'; }
      if (sub) { sub.textContent = 'Pick a plan and read a little each day.'; }
      if (cta) { cta.textContent = 'See the plans →'; }
    }
  }

  /* ---- build the DOM ---- */
  function build() {
    if ($('#hg6-home')) { return; }
    var home = document.createElement('section');
    home.id = 'hg6-home';
    home.setAttribute('aria-label', 'Ehyeh home');
    home.hidden = true;
    home.innerHTML =
      '<div class="hg6-home-inner">' +
        '<h1 class="hg6-greet" id="hg6-greet">Good evening</h1>' +
        '<p class="hg6-date" id="hg6-date"></p>' +
        '<article class="hg6-hero" id="hg6-hero" aria-label="Verse of the day">' +
          '<canvas class="hg6-hero-img" id="hg6-hero-img" role="img" aria-label="Morning mist over a snowy ridge and pine forest"></canvas>' +
          '<div class="hg6-hero-cap">' +
            '<p class="hg6-hero-label">Verse of the Day</p>' +
            '<p class="hg6-ref" id="hg6-ref"></p>' +
          '</div>' +
          '<p class="hg6-verse" id="hg6-verse"></p>' +
          '<div class="hg6-hero-actions">' +
            '<img class="hg6-card-pic" src="assets/pics/verse-day.webp" alt="" aria-hidden="true">' +
            '<button type="button" class="hg6-read" id="hg6-read">' +
              '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 6.2C10.2 4.9 7.9 4.4 5.3 4.6v13c2.6-.2 4.9.3 6.7 1.6 1.8-1.3 4.1-1.8 6.7-1.6v-13c-2.6-.2-4.9.3-6.7 1.6z"/><path d="M12 6.2v13"/></svg>' +
              '<span>Read the chapter</span>' +
            '</button>' +
          '</div>' +
        '</article>' +
        '<button type="button" class="hg6-guided" id="hg6-guided">' +
          '<span class="hg6-guided-main">' +
            '<span class="hg6-guided-label">Guided study</span>' +
            '<span class="hg6-guided-name" id="hg6-guided-name"></span>' +
            '<span class="hg6-guided-sub" id="hg6-guided-sub"></span>' +
            '<span class="hg6-guided-cta" id="hg6-guided-cta"></span>' +
          '</span>' +
          '<img class="hg6-guided-pic" src="assets/pics/guided-study.webp" alt="" aria-hidden="true">' +
        '</button>' +
        '<button type="button" class="hg6-guided hg6-guided-quiet" id="hg6-prayer">' +
          '<span class="hg6-guided-main">' +
            '<span class="hg6-guided-label">Prayer</span>' +
            '<span class="hg6-guided-name">Prayer Request</span>' +
            '<span class="hg6-guided-sub">Send a prayer request to Donnie</span>' +
            '<span class="hg6-guided-cta">Open \u2192</span>' +
          '</span>' +
          '<img class="hg6-guided-pic" src="assets/pics/prayer.webp" alt="" aria-hidden="true">' +
        '</button>' +
      '</div>';
    document.body.appendChild(home);
    paintHeroInto($('#hg6-hero-img'));
    paintHeroInto($('#hg6-guided-thumb'));

    var flowsWrap = document.createElement('section');
    flowsWrap.id = 'hg6-flows';
    flowsWrap.setAttribute('aria-label', 'Guided flows');
    flowsWrap.hidden = true;
    var flowDefs = [
      { id: 'study', pic: 'study-passage.webp', title: 'Guided flow: Study a Passage', sub: 'Read a passage slowly, step by step \u2014 the words, the witnesses, your own notes.' },
      { id: 'compare', pic: 'compare-topic.webp', title: 'Guided flow: Compare a Topic', sub: 'Start from a topic and see its passages side by side, step by step.' },
      { id: 'sermon', pic: 'build-sermon.webp', title: 'Guided flow: Build a Sermon', sub: 'Set up, study, outline, check, and print \u2014 step by step.' }
    ];
    flowDefs.forEach(function (f) {
      var b = document.createElement('button');
      b.type = 'button';
      b.className = 'hg6-flow-entry';
      b.setAttribute('data-hg6-flow-entry', f.id);
      b.setAttribute('data-hg6-start-flow', f.id);
      b.hidden = true;
      b.innerHTML = '<img class="hg6-flow-pic" src="assets/pics/' + f.pic + '" alt="" aria-hidden="true">' +
        '<span class="hg6-flow-label">GUIDED FLOW</span>' +
        '<span class="hg6-flow-title">' + esc(f.title) + '</span>' +
        '<span class="hg6-flow-sub">' + esc(f.sub) + '</span>' +
        '<span class="hg6-flow-cta">Start \u2192</span>';
      b.addEventListener('click', function () {
        var orig = document.querySelector('#hg-home [data-flow="' + f.id + '"]');
        if (orig) { orig.click(); }
      });
      flowsWrap.appendChild(b);
    });
    var mainEl = $('#hagah-main');
    var panelEl = $('#hagah-panel');
    if (mainEl && panelEl) { mainEl.insertBefore(flowsWrap, panelEl); }
    else if (mainEl) { mainEl.appendChild(flowsWrap); }

    var bar = document.createElement('nav');
    bar.id = 'hg6-tabbar';
    bar.setAttribute('aria-label', 'Ehyeh sections');
    var doors = [
      { id: 'home', label: 'Home', icon: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + '<path d="M4.5 11.3 12 4.5l7.5 6.8"/><path d="M6.6 9.8v9.2h10.8V9.8"/><path d="M10 19v-4.8h4V19"/>' + '</svg>' },
      { id: 'bible', label: 'Bible', icon: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + '<path d="M12 6.2C10.2 4.9 7.9 4.4 5.3 4.6v13c2.6-.2 4.9.3 6.7 1.6 1.8-1.3 4.1-1.8 6.7-1.6v-13c-2.6-.2-4.9.3-6.7 1.6z"/><path d="M12 6.2v13"/>' + '</svg>' },
      { id: 'study', label: 'Study', icon: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + '<circle cx="10.8" cy="10.8" r="6.3"/><path d="M15.6 15.6 20.2 20.2"/>' + '</svg>' },
      { id: 'sermon', label: 'Sermon', icon: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + '<path d="M5 19.2 5.8 15 16.4 4.4a2.05 2.05 0 0 1 2.9 0l0.3 0.3a2.05 2.05 0 0 1 0 2.9L9 18.2l-4 1z"/><path d="M14.6 6.2l2.9 2.9"/>' + '</svg>' },
      { id: 'plans', label: 'Plans', icon: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + '<rect x="4.8" y="5.8" width="14.4" height="13.4" rx="2"/><path d="M4.8 10h14.4"/><path d="M8.6 3.8v3.4M15.4 3.8v3.4"/><path d="M9.3 14.6l1.9 1.9 3.4-3.4"/>' + '</svg>' }
    ];
    doors.forEach(function (d) {
      var b = document.createElement('button');
      b.type = 'button';
      b.className = 'hg6-door';
      b.setAttribute('data-hg6-door', d.id);
      b.innerHTML = '<span class="hg6-door-icon" aria-hidden="true">' + d.icon + '</span><span>' + esc(d.label) + '</span>';
      b.addEventListener('click', function () {
        if (d.id === 'home') { goHome(); }
        else if (d.id === 'bible') { goBible(); }
        else if (d.id === 'study') { goStudy(); }
        else if (d.id === 'sermon') { goSermon(); }
        else if (d.id === 'plans') { goPlans(); }
      });
      bar.appendChild(b);
    });
    document.body.appendChild(bar);

    $('#hg6-read').addEventListener('click', function () { if (currentVod) { readChapter(currentVod); } });
    $('#hg6-guided').addEventListener('click', function () { goPlans(); });
    $('#hg6-prayer').addEventListener('click', function () { openPrayerDoor(); });

    /* the floating home button from the rebuild now returns to the v6 home */
    var hb = $('#hg-homebtn');
    if (hb) {
      hb.addEventListener('click', function () { setTimeout(function () { showHome6(); }, 70); });
    }
    /* keep the tab bar out of the first-launch tour, as the tour expects */
    function syncOnboard() {
      var ob = $('#onboard');
      var vis = !!ob && !ob.hidden && window.getComputedStyle(ob).display !== 'none';
      document.body.classList.toggle('hg6-onboard-on', vis);
    }
    syncOnboard();
    if (window.MutationObserver) {
      var ob2 = $('#onboard');
      if (ob2) {
        new MutationObserver(syncOnboard).observe(ob2, { attributes: true, attributeFilter: ['hidden', 'style', 'class'] });
      }
      new MutationObserver(syncOnboard).observe(document.body, { childList: true });
    }
    updateFlowEntries();
    showHome6();
    /* exposed for the walkthrough proof only — same actions as the buttons */
    window.__hg6 = { goHome: goHome, goBible: goBible, goStudy: goStudy, goSermon: goSermon, goPlans: goPlans, vod: function () { return currentVod; }, active: function () { return activeDoor; } };
  }
  /* ------------------------------------------------------------------
     Prayer door (staging addition): a visitor can send Donnie a prayer
     request from the home screen. The panel POSTs JSON to
     https://swava.ai/api/prayer with fetch — the app CSP already allows
     it (connect-src https:) and form-action 'none' does not apply
     because no <form> is used. Nothing is stored in the app. The hidden
     hp field is a honeypot: people never see or fill it; the server
     silently drops any submission that arrives with it filled.
     ------------------------------------------------------------------ */
  var prayerSending = false;
  function prayerSetStatus(text, isError) {
    var s = $('#prayer-status');
    if (s) { s.textContent = text || ''; s.style.color = isError ? 'var(--danger)' : ''; }
  }
  function openPrayerDoor() {
    var d = $('#prayer-dlg');
    if (!d) { return; }
    $('#prayer-form-view').hidden = false;
    $('#prayer-done-view').hidden = true;
    $('#prayer-fallback').hidden = true;
    prayerSetStatus('', false);
    if (typeof d.showModal === 'function') { d.showModal(); } else { d.setAttribute('open', ''); }
    $('#prayer-name').focus();
  }
  function closePrayerDoor() {
    var d = $('#prayer-dlg');
    if (!d) { return; }
    if (d.open) { d.close(); } else { d.removeAttribute('open'); }
  }
  function sendPrayer() {
    if (prayerSending) { return; }
    var name = $('#prayer-name').value.replace(/^\s+|\s+$/g, '');
    var text = $('#prayer-text').value.replace(/^\s+|\s+$/g, '');
    var hp = $('#prayer-hp').value;
    if (name.length > 80) { prayerSetStatus('Please shorten the name to 80 characters or fewer.', true); return; }
    if (text.length < 1) { prayerSetStatus('Please write your prayer request first.', true); $('#prayer-text').focus(); return; }
    if (text.length > 2000) { prayerSetStatus('Please shorten your request to 2,000 characters or fewer.', true); return; }
    prayerSending = true;
    var btn = $('#prayer-send');
    btn.disabled = true;
    prayerSetStatus('Sending...', false);
    fetch('https://swava.ai/api/prayer', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name: name, request: text, hp: hp })
    }).then(function (res) {
      if (!res.ok) { throw new Error('send failed'); }
      return res.json();
    }).then(function (data) {
      if (!data || data.ok !== true) { throw new Error('send failed'); }
      prayerSending = false;
      btn.disabled = false;
      $('#prayer-form-view').hidden = true;
      $('#prayer-done-view').hidden = false;
      $('#prayer-close-2').focus();
    }).catch(function () {
      prayerSending = false;
      btn.disabled = false;
      prayerSetStatus('Sorry - your request could not be sent. Please check your connection and try again.', true);
      $('#prayer-fallback').hidden = false;
    });
  }
  (function wirePrayerDoor() {
    var d = $('#prayer-dlg');
    if (!d) { return; }
    $('#prayer-send').addEventListener('click', sendPrayer);
    $('#prayer-close').addEventListener('click', closePrayerDoor);
    $('#prayer-close-2').addEventListener('click', closePrayerDoor);
    d.addEventListener('cancel', function (e) { e.preventDefault(); closePrayerDoor(); });
  })();

  /* ---- Listen door (staging addition): the study reader's toolbar carries
     a 🔊 Listen button (#st-listen, static markup). Hagah already has a full
     Listen tab inside the Compare · Listen · Memory panel — built-in device
     voices via speechSynthesis, or the user's own voice service with an
     on-device IndexedDB cache — but no control reached it from where a
     passage is read, and the panel always opened on John 1 because the
     reader never told the shell its passage. This wiring only drives the
     app's own UI: open the panel, hand it the reader's current passage via
     the shell's navigate(), open the Listen tab, and press its Play button.
     No speech code lives here — the panel's machinery does all the speaking,
     and its own stopAudio() still stops playback when the user navigates
     away, changes the passage, or switches tabs. */
  (function () {
    var btn = document.getElementById('st-listen');
    if (!btn) { return; }
    btn.addEventListener('click', async function () {
      var bEl = document.getElementById('st-book');
      var cEl = document.getElementById('st-chapter');
      var book = bEl ? parseInt(bEl.value, 10) : NaN;
      var chapter = cEl ? parseInt(cEl.value, 10) : NaN;
      var ok = await gotoTab('clm');
      if (!ok) { return; }
      var app = window.__hagahApp;
      if (app && app.ctx && book >= 1 && chapter >= 1) {
        try { app.ctx.navigate(book, chapter); } catch (e) { /* panel keeps its passage */ }
      }
      var tab = document.querySelector('.clm-tab[data-tab="listen"]');
      if (tab) { tab.click(); await sleep(120); }
      for (var i = 0; i < 25; i++) {
        var btns = document.querySelectorAll('#hagah-panel .clm-btn');
        for (var j = 0; j < btns.length; j++) {
          if (btns[j].textContent.indexOf('Play') !== -1) { btns[j].click(); return; }
        }
        await sleep(120);
      }
    });
  })();

  function ready(fn) {
    if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', fn); }
    else { fn(); }
  }
  ready(function () { setTimeout(build, 60); });
})();

